/* eslint-disable @typescript-eslint/no-explicit-any */
import { router } from "expo-router";
import { fmtIndex } from "@cricket/engine/util.js";

// Where a tap goes. The player link is the site's own (`/player/<index>?stat=&line=&fmt=&scope=`), so the two can share links later. `as never`: the typed-routes types
// are generated by the dev server and are not there for a plain type-check.

export const fixturePath = (id: string) => `/fixture/${encodeURIComponent(id)}`;

/** A match's ground page (the site's `/fixture/:id/ground`) and a ground by its stats index (`/venue/:idx`). */
export const groundPath = (id: string) => `${fixturePath(id)}/ground`;
export const venuePath = (idx: number) => `/venue/${idx}`;

/** One fancy market's page (the site's `/fixture/:id/fancy?fm=&sc=`). */
export function fancyMarketPath(id: string, o: { fm: string; sc?: number | string | null; mw?: number | string | null; mv?: string | null; ml?: number | string | null }) {
  const q = new URLSearchParams();
  if (o.fm) q.set("fm", o.fm);
  if (o.sc != null && o.sc !== "" && String(o.sc) !== "-1") q.set("sc", String(o.sc));
  if (o.mw != null && o.mw !== "" && Number(o.mw) !== 20) q.set("mw", String(o.mw));
  if (o.mv === "1") q.set("mv", "1");
  if (o.ml != null && o.ml !== "") q.set("ml", String(o.ml));
  const s = q.toString();
  return `${fixturePath(id)}/fancy${s ? `?${s}` : ""}`;
}

/** The player link: the site's own parameters (`stat`, `line`, `fmt` as the format's number, `scope` for a Test side's innings, `start` for which priced match), plus `team` for the shirt. */
export const playerPath = (r: { idx: number; stat: string; line: number; fmt: string; inn?: number; team?: string; start?: string }) =>
  `/player/${r.idx}?stat=${r.stat}&line=${r.line}&fmt=${fmtIndex(r.fmt)}${r.start ? `&start=${encodeURIComponent(r.start)}` : ""}${r.inn ? `&scope=${r.inn}` : ""}${r.team ? `&team=${encodeURIComponent(r.team)}` : ""}`;

let lastPush = 0;
/**
 * `router.push` for a tap: a second tap on the same screen within 700 ms is dropped (when the phone lags, an impatient second tap opened the page twice), and the push waits one
 * frame so the pressed state is drawn before the new screen starts to mount.
 */
export function push(path: string | { pathname: string; params?: Record<string, string> }) {
  const t = Date.now();
  if (t - lastPush < 700) return;
  lastPush = t;
  requestAnimationFrame(() => router.push(path as never));
}

/** A fixture's page (`/fixture/<id>`). A fixture with no id has no page. */
export function openFixture(f: { id?: string }) {
  if (f?.id) push(fixturePath(f.id));
}

/** A player's page, opened on the line of the row that was tapped. */
export function openPlayer(r: Parameters<typeof playerPath>[0]) {
  push(playerPath(r));
}

/** Back one page, or to Fixtures when the app was opened on this page. */
export function goBack() {
  if (router.canGoBack()) router.back();
  else router.replace("/" as never);
}
